import{connectedWorkspaceInspection}from'../../src/components/ConnectedWorkspace.tsx';
import{createOpenCylinderTerrain}from'../../src/terrain/open-cylinder.ts';import{IndexedDisplayCache}from'../../src/rendering/indexed-display-cache.ts';import{openCylinderRasterSteps}from'../../src/rendering/open-cylinder-raster.ts';import{OpenCylinderWebGLRenderer}from'../../src/rendering/open-cylinder-webgl.ts';import{settledRasterBudget}from'../../src/rendering/raster-quality.ts';
/** Real active backing versus a fresh field reconstructed from its exact words. */
export async function flatRingCurrentOutputProof(backend:'cpu'|'webgl2'){
 const s=connectedWorkspaceInspection().snapshot()as any,t=createOpenCylinderTerrain({terrainId:s.metadata.terrainId,geometry:s.metadata.geometry,resolution:s.metadata.representation.resolution}),words=new Float32Array(Uint32Array.from(s.words).buffer);for(let i=0;i<t.sampleCount;i++)t.write(t.keyAt(i),words[i]!);const cache=new IndexedDisplayCache(t,131072,'proof budget');for(const _ of cache.prepare())void _;
 const source=document.createElement('canvas'),actual=document.querySelector<HTMLCanvasElement>(backend==='cpu'?'.cylinder-canvas':'.cylinder-gpu')!;let gpu:OpenCylinderWebGLRenderer|undefined;
 if(backend==='webgl2'){gpu=new OpenCylinderWebGLRenderer(source,cache,()=>{},true);await gpu.whenReady();gpu.present(s.view,s.size,s.appearance);}else{const job=openCylinderRasterSteps(cache,s.view,s.size,settledRasterBudget(s.size,devicePixelRatio,matchMedia('(pointer: coarse)').matches),undefined,s.appearance);let step=job.next(),at=performance.now();while(!step.done){if(performance.now()-at>5){await new Promise(r=>setTimeout(r,0));at=performance.now();}step=job.next();}const raster=step.value,tile=document.createElement('canvas');tile.width=raster.columns;tile.height=raster.rows;tile.getContext('2d')!.putImageData(new ImageData(raster.pixels as Uint8ClampedArray<ArrayBuffer>,raster.columns,raster.rows),0,0);source.width=actual.width;source.height=actual.height;const ctx=source.getContext('2d')!;ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(tile,0,0,source.width,source.height);}
 if(actual.width!==source.width||actual.height!==source.height)throw Error('Current/fresh backing dimensions differ.');const capture=(c:HTMLCanvasElement)=>{const tile=document.createElement('canvas');tile.width=c.width;tile.height=c.height;const ctx=tile.getContext('2d',{willReadFrequently:true})!;ctx.drawImage(c,0,0);return{data:ctx.getImageData(0,0,tile.width,tile.height).data,png:tile.toDataURL()};},expected=capture(source),current=backend==='cpu'?capture(actual):await new Promise<ReturnType<typeof capture>>((resolve,reject)=>{const draw=WebGL2RenderingContext.prototype.drawArrays,timer=window.setTimeout(()=>{WebGL2RenderingContext.prototype.drawArrays=draw;reject(Error('No actual GPU submission'));},10000);WebGL2RenderingContext.prototype.drawArrays=function(...args){Reflect.apply(draw,this,args);if(this.canvas===actual){clearTimeout(timer);WebGL2RenderingContext.prototype.drawArrays=draw;queueMicrotask(()=>resolve(capture(actual)));}};window.__flatRingEditor!.setView(s.view);});
 let different=0,maxDifference=0,alphaDifferent=0;for(let i=0;i<current.data.length;i++)if(current.data[i]!==expected.data[i]){different++;maxDifference=Math.max(maxDifference,Math.abs(current.data[i]!-expected.data[i]!));if(i%4===3)alphaDifferent++;}const result={backend,width:source.width,height:source.height,different,maxDifference,alphaDifferent,currentPng:current.png,freshPng:expected.png};gpu?.dispose();cache.dispose();return result;
}
